from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NEW_YORK)

        spy_security = self.AddEquity(
            "SPY", Resolution.MINUTE, Market.USA, fillForward=False
        )
        spy_security.SetDataNormalizationMode(DataNormalizationMode.RAW)
        self.spy = spy_security.Symbol

        option_security = self.AddOption(
            "SPY", Resolution.MINUTE, Market.USA, fillForward=False
        )
        self.option_symbol = option_security.Symbol
        option_security.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover_end = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.blocked_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self.five_minute_consolidator
        )

    def OnFiveMinuteBar(self, bar):
        # No history is requested: this window is warmed only by backtest-period bars.
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        if (self.previous_fast is not None and
                self.previous_fast <= self.previous_slow and
                fast > slow):
            bar_end_time = bar.EndTime.time()
            if time(9, 45) <= bar_end_time <= time(14, 30):
                self.pending_crossover_end = bar.EndTime

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safeguard()
        self._handle_option_exits(slice)
        self._clear_closed_position_state()

        if self.pending_crossover_end == self.Time:
            self.pending_crossover_end = None
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None:
            return

        if self._has_open_entry_order():
            return

        try:
            chain = slice.OptionChains[self.option_symbol]
        except KeyError:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped; no expiry at least 7 calendar days out.")
            return

        selected_expiry = eligible_expiries[0]
        spot = self.Securities[self.spy].Price
        minimum_strike = 1.01 * spot

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def _handle_option_exits(self, slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.hour == 15 and self.Time.minute == 45:
            if self._previous_trading_day(expiry_date) == self.Time.date():
                self._submit_exit("pre-expiration time stop")
                return

        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_safeguard(self):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity > 0:
                self._submit_exit("expiration safeguard")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating."
            )
            self.Liquidate(self.spy)

    def _submit_exit(self, reason):
        if self.held_contract is None or self._has_open_exit_order():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted ({reason}): {self.held_contract}.")

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _has_open_entry_order(self):
        if self.entry_order_id is None:
            return False

        return any(
            order.Id == self.entry_order_id
            for order in self.Transactions.GetOpenOrders()
        )

    def _has_open_exit_order(self):
        if self.exit_order_id is None or self.held_contract is None:
            return False

        return any(
            order.Id == self.exit_order_id
            for order in self.Transactions.GetOpenOrders(self.held_contract)
        )

    def _clear_closed_position_state(self):
        if self.held_contract is None:
            return

        if (self.Portfolio[self.held_contract].Quantity == 0 and
                not self._has_open_exit_order() and
                not self._has_open_entry_order()):
            self.held_contract = None
            self.entry_fill_price = None
            self.entry_order_id = None
            self.exit_order_id = None

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.FILLED and orderEvent.FillQuantity > 0:
                self.held_contract = orderEvent.Symbol
                self.entry_fill_price = float(orderEvent.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {orderEvent.Symbol} "
                    f"at {orderEvent.FillPrice}."
                )
            elif orderEvent.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_id = None
                self.Debug(f"{self.Time}: Entry order did not complete.")

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.FILLED:
                self.Debug(
                    f"{self.Time}: Exit filled: {orderEvent.Symbol} "
                    f"at {orderEvent.FillPrice}."
                )
                self.exit_order_id = None
            elif orderEvent.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None
