from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(-100, 100, timedelta(days=0), timedelta(days=730))
        self.option_symbol = option.symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.window_end = None
        self.window_bars = []

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None

        self.entry_order_id = None
        self.entry_expiry = None
        self.exit_order_id = None
        self.no_entry_date = None

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()

        # Exit processing is evaluated on every minute Slice.
        self._process_expiration_exit()
        self._process_time_stop()
        self._process_profit_target(data)

        if data.Bars.ContainsKey(self.spy):
            self._update_five_minute_bars(data.Bars[self.spy], data)

    def _update_five_minute_bars(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime

        # Regular-session minute bars end from 09:31 through 16:00 New York time.
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        period_end = end_time.replace(
            minute=(end_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        # A bar ending exactly on a five-minute boundary belongs to that boundary.
        # Examples: 09:31-09:35 -> period ending 09:35.
        if end_time.minute % 5 != 0:
            period_end += timedelta(minutes=5)

        if self.window_end is None or period_end != self.window_end:
            # Any unfinished prior interval is discarded: no synthesis or fill-forward.
            self.window_end = period_end
            self.window_bars = []

        expected_end = (
            self.window_end - timedelta(minutes=5 - len(self.window_bars))
        )

        # Require consecutive actual minute bars. A gap invalidates the interval.
        if end_time != expected_end:
            self.window_bars = []
            expected_end = self.window_end - timedelta(minutes=5)

            if end_time != expected_end:
                return

        self.window_bars.append(minute_bar)

        if end_time != self.window_end:
            return

        completed_bars = self.window_bars
        self.window_end = None
        self.window_bars = []

        if len(completed_bars) != 5:
            return

        expected_times = [
            end_time - timedelta(minutes=4 - index)
            for index in range(5)
        ]
        if any(bar.EndTime != expected_times[index]
               for index, bar in enumerate(completed_bars)):
            return

        self._on_completed_five_minute_bar(end_time, completed_bars[-1].Close, data)

    def _on_completed_five_minute_bar(self, bar_end: datetime, close: float, data: Slice):
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if time(9, 45) <= bar_end.time() <= time(14, 30):
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Securities[self.held_contract].Holdings.Invested:
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if not data.Bars.ContainsKey(self.spy):
            self.debug("Entry skipped: no current SPY price.")
            return

        spy_price = data.Bars[self.spy].Close
        minimum_expiry = self.Time.date() + timedelta(days=7)

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol.Underlying == self.spy:
                    contracts.append(contract)

        if not contracts:
            self.debug("Entry skipped: no SPY option chain in Slice.")
            return

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.CALL
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no eligible call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        ticket = self.market_order(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_expiry = selected.Expiry.date()

        self.debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike:.2f}."
        )

    def _process_profit_target(self, data: Slice):
        if not self._has_open_option_position() or self.entry_fill_price is None:
            return

        if self.exit_order_id is not None:
            return

        if not data.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = data.QuoteBars[self.held_contract]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("profit target")

    def _process_time_stop(self):
        if not self._has_open_option_position() or self.held_expiry is None:
            return

        if self.exit_order_id is not None:
            return

        previous_trading_day = self._previous_spy_trading_day(self.held_expiry)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() == time(15, 45)
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_exit(self):
        expiration = self.held_expiry if self.held_expiry is not None else self.entry_expiry

        if expiration is None or self.Time.date() < expiration:
            return

        self.no_entry_date = self.Time.date()

        if self.entry_order_id is not None:
            self.transactions.cancel_order(self.entry_order_id)
            self.debug("Canceled open entry order at expiration processing.")

        if self._has_open_option_position() and self.exit_order_id is None:
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if not self._has_open_option_position():
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            self.transactions.cancel_order(order.Id)

        quantity = self.Securities[self.held_contract].Holdings.Quantity
        if quantity != 0:
            ticket = self.market_order(self.held_contract, -quantity)
            self.exit_order_id = ticket.OrderId
            self.debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Securities[self.spy].Holdings.Quantity
        if spy_quantity == 0:
            return

        existing_orders = self.transactions.get_open_orders(self.spy)
        if not existing_orders:
            self.market_order(self.spy, -spy_quantity)
            self.debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

