        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # With regular-hours minute SPY data, the first bar is 09:30-09:35.
        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window) / self.fast_window.Count
        current_slow = sum(self.slow_window) / self.slow_window.Count

        if self.previous_fast is not None and self.previous_slow is not None:
            bar_end = bar.EndTime.time()
            eligible_time = (
                bar_end >= datetime(2000, 1, 1, 9, 45).time() and
                bar_end <= datetime(2000, 1, 1, 14, 30).time()
            )

            if (eligible_time and
                    self.previous_fast <= self.previous_slow and
                    current_fast > current_slow):
                self.pending_entry_signal = True

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            expiry_date = self.held_contract.ID.Date.date()
            if self.Time.date() >= expiry_date:
                self.no_entry_date = self.Time.date()
                self.Debug(
                    f"Expiration safeguard: liquidating {self.held_contract} on {self.Time.date()}"
                )
                self._submit_exit("expiration safeguard")

        self._check_profit_target(data)

        if not self.pending_entry_signal:
            return

        # A signal is evaluated exactly once on the Slice following its completed bar.
        self.pending_entry_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self._has_open_entry_order() or self._has_option_position() or self._has_open_exit_order():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in calls)
        minimum_strike = 1.01 * current_spy_price

        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no call at {selected_expiry} with strike >= {minimum_strike:.2f}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: 1 {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_fill_price:.2f}."
                )
                self._schedule_contract_exits(self.held_contract)
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.exit_ticket = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Exit order closed without fill: {order_event.Symbol}.")
                self.exit_ticket = None

    def _check_profit_target(self, data):
        if not self._has_option_position() or self.entry_fill_price is None:
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._cancel_open_exit_orders()
            self._submit_exit(
                f"50% profit target reached (midpoint {midpoint:.2f}, "
                f"entry {self.entry_fill_price:.2f})"
            )

    def _schedule_contract_exits(self, contract_symbol):
        expiry_date = contract_symbol.ID.Date.date()
        previous_trading_day = self._previous_spy_trading_day(expiry_date)

        self.Schedule.On(
            self.DateRules.On(
                previous_trading_day.year,
                previous_trading_day.month,
                previous_trading_day.day
            ),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

        self.Schedule.On(
            self.DateRules.On(expiry_date.year, expiry_date.month, expiry_date.day),
            self.TimeRules.AfterMarketOpen(self.spy, 0),
            self._expiration_processing
        )

    def _time_stop(self):
        if self._has_option_position():
            self._submit_exit("15:45 pre-expiration time stop")

    def _expiration_processing(self):
        if self._has_option_position():
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration processing safeguard")

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if not self._has_option_position() or self._has_open_exit_order():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {self.held_contract}; reason: {reason}.")

    def _cancel_open_exit_orders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order.")

    def _has_option_position(self):
        return (
            self.held_contract is not None and
            self.Portfolio[self.held_contract].Quantity > 0
        )

    def _has_open_entry_order(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _has_open_exit_order(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        has_open_equity_exit = any(
            order.Quantity * quantity < 0
            for order in self.Transactions.GetOpenOrders(self.spy)
        )

        if not has_open_equity_exit:
            self.Debug(
                f"Unexpected SPY equity position ({quantity}) from exercise/assignment; "
                "liquidating immediately."
            )
            self.MarketOrder(self.spy, -quantity)
