            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no call at {selected_expiry} with strike >= {minimum_strike:.2f}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: 1 {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_fill_price:.2f}."
                )
                self._schedule_contract_exits(self.held_contract)
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.exit_ticket = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Exit order closed without fill: {order_event.Symbol}.")
                self.exit_ticket = None

