        self._previous_slow = slow

        eligible_time = (
            (bar_end_time.Hour > 9 or
             (bar_end_time.Hour == 9 and bar_end_time.Minute >= 45))
            and
            (bar_end_time.Hour < 14 or
             (bar_end_time.Hour == 14 and bar_end_time.Minute <= 30))
        )

