        self.ProcessExpirationSafety()
        self.ProcessTimeStop()
        self.ProcessProfitTarget(slice)

        if self.pending_five_minute_bar is not None:
            bar = self.pending_five_minute_bar
            self.pending_five_minute_bar = None
            self.ProcessFiveMinuteBar(bar, slice)

    def ProcessFiveMinuteBar(self, bar, slice):
        self.closes.Add(float(bar.Close))

        # A preceding 20-bar slow average requires 21 completed bars.
        if self.closes.Count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(0, 5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(0, 20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not eligible_time or not bullish_cross:
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        if self.HasOptionHolding() or self.entry_order_id is not None:
            return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        chain = slice.OptionChains.get(self.option_symbol)
        spy_bar = slice.Bars.get(self.spy)

        if chain is None or spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: Entry skipped - missing current option chain or SPY bar.")
            return

        today = self.Time.date()
        eligible_contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        ]

        if not eligible_contracts:
            self.Debug(f"{self.Time}: Entry skipped - no expiration at least 7 calendar days away.")
            return

        expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        minimum_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped - no qualifying call at expiration {expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol} "
            f"(expiry {selected.Expiry.date()}, strike {selected.Strike})."
        )

    def ProcessProfitTarget(self, slice):
        if not self.HasOptionHolding() or self.entry_fill_price is None:
            return

        if self.exit_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = chain.Contracts.get(self.held_contract)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit(
                f"{self.Time}: Profit target reached for {self.held_contract}; midpoint {midpoint:.2f}."
            )

    def ProcessTimeStop(self):
