            return

        if self.exit_order_id is not None:
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            self.contract_expiry, False
        ).date()

        if self.Time.date() == previous_trading_day and self.Time.time() == time(15, 45):
            self.SubmitExit(
                f"{self.Time}: 15:45 pre-expiration exit for {self.held_contract}."
            )

    def ProcessExpirationSafety(self):
        if not self.HasOptionHolding() or self.contract_expiry is None:
            return

        if self.Time.date() < self.contract_expiry.date():
            return

        self.expiration_blocked_date = self.Time.date()
        self.SubmitExit(
            f"{self.Time}: Expiration safety liquidation for {self.held_contract}."
        )

    def SubmitExit(self, message):
        if not self.HasOptionHolding():
            return

        if self.exit_order_id is not None:
            return

        self.CancelOpenExitOrders()

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(message)

    def CancelOpenExitOrders(self):
        for order in self.Transactions.GetOpenOrders():
            if self.held_contract is not None and order.Symbol == self.held_contract:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order.")

    def HandleUnexpectedSpyHolding(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment holding of "
                f"{spy_quantity}; submitting market liquidation."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def HasOptionHolding(self):
        return (
            self.held_contract is not None and
            self.Portfolio[self.held_contract].Quantity != 0
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id:
                self.held_contract = order_event.Symbol
                self.contract_expiry = order_event.Symbol.ID.Date
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None

                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} at "
                    f"{self.entry_fill_price:.2f}."
                )

            elif order_event.OrderId == self.exit_order_id:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None

                if self.held_contract == order_event.Symbol:
                    self.held_contract = None
                    self.contract_expiry = None
                    self.entry_fill_price = None

        elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            if order_event.OrderId == self.entry_order_id:
                self.entry_order_id = None
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} did not remain open.")

            elif order_event.OrderId == self.exit_order_id:
                self.exit_order_id = None
                self.Debug(f"{self.Time}: Exit order {order_event.OrderId} did not remain open.")
