from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            False,  # no fill-forward: do not synthesize missing minute/five-minute bars
            1,
            False,
            DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        self.spy_option = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                    .Strikes(-100, 100)
                                    .Expiration(timedelta(0), timedelta(730))
        )

        self.fast_sma = SimpleMovingAverage(5)
        self.slow_sma = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_entry_bar_end = None
        self.no_entry_date = None

        self.held_contract = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.pending_entry_contract = None
        self.exit_order_id = None
        self.equity_exit_order_id = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.OnScheduledTimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        # Consolidator only receives actual source minute bars; no missing interval is filled here.
        self.fast_sma.Update(bar.EndTime, bar.Close)
        self.slow_sma.Update(bar.EndTime, bar.Close)

        if not (self.fast_sma.IsReady and self.slow_sma.IsReady):
            return

        current_fast = float(self.fast_sma.Current.Value)
        current_slow = float(self.slow_sma.Current.Value)

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if crossover and eligible_time:
            # This is consumed only by the Slice at this same bar-close timestamp.
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyEquityPosition()
        self.HandleExpirationProcessing()

        if self.held_contract is not None:
            self.EvaluateProfitTarget(data)

        if self.pending_entry_bar_end is not None:
            signal_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            # Do not queue missed signals for later Slices.
            if signal_time != self.Time:
                return

            self.TryEnterFromCurrentSlice(data)

    def TryEnterFromCurrentSlice(self, data):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.IsOrderOpen(self.entry_order_id):
            return

        if self.IsOrderOpen(self.exit_order_id):
            return

        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY minute bar.")
            return

        spy_price = float(data.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.pending_entry_contract = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def EvaluateProfitTarget(self, data):
        if not self.Portfolio[self.held_contract].Invested:
            self.ClearClosedPosition()
            return

        if self.IsOrderOpen(self.exit_order_id):
            return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        contract = self.GetContractFromSlice(data, self.held_contract)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("profit target")

    def OnScheduledTimeStop(self):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            self.ClearClosedPosition()
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() == self.PreviousTradingDay(expiry_date):
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() < expiry_date:
            return

        self.no_entry_date = self.Time.date()

        if self.Portfolio[self.held_contract].Invested:
            self.SubmitExit("expiration processing")

    def HandleUnexpectedSpyEquityPosition(self):
        if not self.Portfolio[self.spy].Invested:
            self.equity_exit_order_id = None
            return

        if self.IsOrderOpen(self.equity_exit_order_id):
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.spy, -quantity)
            self.equity_exit_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            self.ClearClosedPosition()
            return

        if self.IsOrderOpen(self.exit_order_id):
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self.ClearClosedPosition()
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({0}): {1}".format(reason, self.held_contract))

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.pending_entry_contract = None
                self.Debug(
                    "Entry filled: {0} at {1:.2f}".format(
                        self.held_contract,
                        self.entry_fill_price
                    )
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.pending_entry_contract = None
                self.Debug("Entry order did not complete: {0}".format(order_event.Status))

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1:.2f}".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.exit_order_id = None
                self.ClearClosedPosition()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_exit_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_exit_order_id = None

    def GetContractFromSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time(0, 0)),
            False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
