        prior_trading_day = exchange_hours.GetPreviousTradingDay(self.held_expiry)

        if self.Time.date() == prior_trading_day.date():
            self.SubmitOptionExit("15:45 pre-expiration time stop")

    def SubmitOptionExit(self, reason):
        if self.held_contract is None or self.IsExitOrderOpen():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_order_id is not None:
            old_ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if old_ticket is not None:
                old_ticket.Cancel()

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def FlattenUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        if self.spy_flatten_order_id is not None:
            order = self.Transactions.GetOrderById(self.spy_flatten_order_id)
            if order is not None and order.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.spy_flatten_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Unexpected SPY position from exercise/assignment; "
            f"submitted market liquidation."
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.FillQuantity > 0 and self.held_contract is None:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_contract} at "
                    f"{self.entry_fill_price}."
                )

            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol}.")
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_fill_price = None
                self.exit_order_id = None

