            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_flatten_order_id = None

        self.FlattenUnexpectedSpyPosition()

    def IsOptionPositionOpen(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def IsEntryOrderOpen(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def IsExitOrderOpen(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
