        self.SubscriptionManager.AddConsolidator(self.spy, self._five_minute_consolidator)

        # Handles any position that survives into its expiration date.
        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self._on_expiration_processing
        )

        # Applies the required previous-trading-day exit rule.
        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._on_expiration_eve_time_stop
        )

