            return

        self._liquidate_expired_option_if_needed()

        if self._held_contract is not None:
            self._check_profit_target(data)

        # A signal is usable only on the Slice at the consolidated bar's close.
        if self._entry_signal_due_time is not None:
            due_time = self._entry_signal_due_time
            self._entry_signal_due_time = None

            if self.Time == due_time:
                self._try_enter(data)
            elif self.Time < due_time:
                # Defensive only; normally consolidator events occur before OnData.
                self._entry_signal_due_time = due_time

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        self._five_minute_closes.append(float(bar.Close))
        if len(self._five_minute_closes) > 20:
            self._five_minute_closes.pop(0)

        # Missing five-minute intervals never reach this handler, so no value is filled.
        if len(self._five_minute_closes) < 20:
            return

        fast = sum(self._five_minute_closes[-5:]) / 5.0
        slow = sum(self._five_minute_closes) / 20.0

        is_bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        bar_end = bar.EndTime.time()
        if is_bullish_cross and time(9, 45) <= bar_end <= time(14, 30):
            self._entry_signal_due_time = bar.EndTime

