        if self._no_entries_date == self.Time.date():
            return

        if self._pending_entry_symbol is not None or self._has_option_position():
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: skipped entry; no current SPY trade bar.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_contracts = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug(f"{self.Time}: skipped entry; no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        minimum_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call at expiration {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))

        self._pending_entry_symbol = selected.Symbol
        self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted entry for {selected.Symbol} "
            f"(expiry {selected.Expiry.date()}, strike {selected.Strike})."
        )

