            return

        if self._has_open_exit_order():
            return

        quote_bar = data.QuoteBars.get(self._held_contract)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_option_exit("50% profit target")

    def _on_expiration_eve_time_stop(self):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        expiry_date = self._held_contract.ID.Date.date()
        next_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(
            self.Time, False
        )

        # This is the final trading session before the calendar expiration date.
        if self.Time.date() < expiry_date and next_open.date() >= expiry_date:
            self._submit_option_exit("15:45 expiration-eve time stop")

    def _on_expiration_processing(self):
        self._liquidate_expired_option_if_needed()

    def _liquidate_expired_option_if_needed(self):
        if self._held_contract is None or not self.Portfolio[self._held_contract].Invested:
            return

        if self._held_contract.ID.Date.date() <= self.Time.date():
            self._no_entries_date = self.Time.date()
            self._submit_option_exit("expiration processing")

    def _submit_option_exit(self, reason: str):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0 or self._has_open_exit_order():
            return

        # There should only be one exit order, but cancel any pre-existing sell order first.
        for order in self.Transactions.GetOpenOrders(self._held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing exit order")

        self.MarketOrder(self._held_contract, -quantity)
        self.Debug(f"{self.Time}: submitted exit for {self._held_contract}; {reason}.")

    def _has_open_exit_order(self) -> bool:
        if self._held_contract is None:
            return False

        return any(
            order.Quantity < 0
            for order in self.Transactions.GetOpenOrders(self._held_contract)
        )

    def _has_option_position(self) -> bool:
        if self._held_contract is not None and self.Portfolio[self._held_contract].Invested:
            return True

        for symbol, security in self.Securities.items():
            if security.Type == SecurityType.Option and self.Portfolio[symbol].Invested:
                return True

        return False

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Symbol == self._pending_entry_symbol:
            if orderEvent.Status == OrderStatus.Filled:
                self._held_contract = orderEvent.Symbol
                self._entry_fill_price = float(orderEvent.FillPrice)
                self._pending_entry_symbol = None
                self.Debug(
                    f"{self.Time}: entry filled for {orderEvent.Symbol} "
                    f"at {self._entry_fill_price:.2f}."
                )
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: entry failed for {orderEvent.Symbol}.")
                self._pending_entry_symbol = None
            return

        if orderEvent.Symbol == self._held_contract and orderEvent.Status == OrderStatus.Filled:
            if self.Portfolio[orderEvent.Symbol].Quantity == 0:
                self.Debug(
                    f"{self.Time}: exit filled for {orderEvent.Symbol} "
                    f"at {float(orderEvent.FillPrice):.2f}."
                )
                self._held_contract = None
                self._entry_fill_price = None

    def OnAssignmentOrderEvent(self, assignmentEvent: OrderEvent):
        self._liquidate_unexpected_spy_position("assignment callback")

    def _liquidate_unexpected_spy_position(self, reason: str) -> bool:
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return False

        self._no_entries_date = self.Time.date()

        if not self.Transactions.GetOpenOrders(self.spy):
            self.MarketOrder(self.spy, -quantity)
            self.Debug(
                f"{self.Time}: unexpected SPY position ({reason}); "
                f"submitted liquidation for {quantity} shares."
            )

        return True
