from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(
                timedelta(days=0), timedelta(days=730)
            )
        )

        self.five_minute_closes = deque(maxlen=21)
        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_valid = True
        self.last_minute_end = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.time_stop_date = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._handle_position_exits(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar, data)

    def _update_five_minute_bar(self, minute_bar: TradeBar, data: Slice):
        bar_end = minute_bar.EndTime
        bar_time = bar_end.time()

        # Regular-session minute bars end from 09:31 through 16:00.
        if bar_time < time(9, 31) or bar_time > time(16, 0):
            return

        minutes_to_boundary = (5 - (bar_end.minute % 5)) % 5
        current_bucket_end = (bar_end + timedelta(minutes=minutes_to_boundary)).replace(
            second=0, microsecond=0
        )
        expected_first_end = current_bucket_end - timedelta(minutes=4)

        if self.bucket_end != current_bucket_end:
            self.bucket_end = current_bucket_end
            self.bucket_bars = []
            self.bucket_valid = (bar_end == expected_first_end)
            self.last_minute_end = None

        if self.last_minute_end is not None:
            if bar_end != self.last_minute_end + timedelta(minutes=1):
                self.bucket_valid = False

        self.bucket_bars.append(minute_bar)
        self.last_minute_end = bar_end

        if bar_end != self.bucket_end:
            return

        # Do not synthesize a five-minute bar if any minute in its interval is absent.
        if self.bucket_valid and len(self.bucket_bars) == 5:
            five_minute_close = self.bucket_bars[-1].Close
            self._on_completed_five_minute_bar(bar_end, five_minute_close, data)

        self.bucket_end = None
        self.bucket_bars = []
        self.last_minute_end = None

